3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes the submitted telephone on create into E.164 form via {@link OwnerTelephones}.
9	 * The E.164 value is written back onto the request in place (the {@code @Val} object is
10	 * shared with later steps) so downstream steps store and return it; a number that cannot
11	 * form valid E.164 is rejected with 400 via {@link InvalidTelephoneException}.
12	 */
13	public class NormalizeOwnerTelephone {
14	
15	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
16	        String telephone = request.getTelephone();
17	        String e164 = OwnerTelephones.toE164(telephone);
18	        if (e164 == null) {
19	            throw new InvalidTelephoneException(telephone);
20	        }
21	        request.setTelephone(e164);
22	    }
23	}
