1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Rejects creating an owner whose E.164 telephone is already used by any other owner.
11	 * Runs after {@link NormalizeOwnerTelephone}, so the request already carries the E.164
12	 * value and is compared as-is; existing owners' telephones are converted to E.164 via the
13	 * shared {@link OwnerTelephones} rule before comparing, making the check independent of how
14	 * a stored number was originally formatted. A match is a 409 via
15	 * {@link DuplicateTelephoneException}.
16	 */
17	public class EnsureUniqueOwnerTelephone {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateTelephoneException {
21	        String telephone = request.getTelephone();
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (telephone.equals(OwnerTelephones.toE164(existing.getTelephone()))) {
24	                throw new DuplicateTelephoneException(telephone);
25	            }
26	        }
27	    }
28	}
