1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Single source of truth for what a "normalized" owner telephone is: the number in
5	 * <a href="https://en.wikipedia.org/wiki/E.164">E.164</a> form. Used by
6	 * {@link NormalizeOwnerTelephone} when storing and by {@link EnsureUniqueOwnerTelephone}
7	 * when comparing against existing owners, so the rule cannot drift between the two steps.
8	 *
9	 * <p>The rule: spaces, dashes and brackets are stripped. If a leading {@code '+'} (and
10	 * therefore an explicit country code) is present it is kept; otherwise country code
11	 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national
12	 * digits. The result must have 8 to 15 digits after the {@code '+'}, else it is invalid.
13	 */
14	final class OwnerTelephones {
15	
16	    private OwnerTelephones() {
17	    }
18	
19	    /**
20	     * Returns the E.164 form of {@code telephone}, or {@code null} if it cannot form a
21	     * valid E.164 number (non-digit characters remaining, or not 8-15 digits after the
22	     * {@code '+'}).
23	     */
24	    static String toE164(String telephone) {
25	        if (telephone == null) {
26	            return null;
27	        }
28	        String trimmed = telephone.trim();
29	        boolean explicitCountryCode = trimmed.startsWith("+");
30	        // Strip spaces, dashes and brackets; keep a leading '+' and the digits.
31	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
32	        String digits = explicitCountryCode ? stripped.substring(1) : stripped;
33	        if (!digits.matches("\\d+")) {
34	            return null;
35	        }
36	        if (!explicitCountryCode) {
37	            // No country code: assume +61 and drop a single leading national '0'.
38	            if (digits.startsWith("0")) {
39	                digits = digits.substring(1);
40	            }
41	            digits = "61" + digits;
42	        }
43	        if (digits.length() < 8 || digits.length() > 15) {
44	            return null;
45	        }
46	        return "+" + digits;
47	    }
48	}
