117	    }
118	
119	    /**
120	     * The owner's initials: the upper-cased first letters of firstName and
121	     * lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
122	     */
123	    @Transient
124	    public String getInitials() {
125	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
126	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
127	    }
128	
129	    protected Set<Pet> getPetsInternal() {
130	        if (this.pets == null) {
131	            this.pets = new HashSet<>();
132	        }
133	        return this.pets;
134	    }
135	
136	    protected void setPetsInternal(Set<Pet> pets) {
137	        this.pets = pets;
138	    }
139	
140	    public List<Pet> getPets() {
141	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
142	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
143	        return Collections.unmodifiableList(sortedPets);
144	    }
145	
146	    public void setPets(List<Pet> pets) {
147	        this.pets = new HashSet<>(pets);
148	    }
149	
150	    public void addPet(Pet pet) {
151	        getPetsInternal().add(pet);
152	        pet.setOwner(this);
153	    }
154	
155	    /**
156	     * Return the Pet with the given name, or null if none found for this Owner.
157	     *
158	     * @param name to test
159	     * @return true if pet name is already in use
160	     */
161	    public Pet getPet(String name) {
162	        return getPet(name, false);
163	    }
164	
165	    /**
166	     * Return the Pet with the given name, or null if none found for this Owner.
167	     *
168	     * @param name to test
169	     * @return true if pet name is already in use
170	     */
171	    public Pet getPet(String name, boolean ignoreNew) {
172	        name = name.toLowerCase();
173	        for (Pet pet : getPetsInternal()) {
174	            if (!ignoreNew || !pet.isNew()) {
175	                String compName = pet.getName();
176	                compName = compName.toLowerCase();
177	                if (compName.equals(name)) {
178	                    return pet;
179	                }
180	            }
181	        }
182	        return null;
183	    }
184	
185	    public Pet getPet(Integer petId) {
186	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
187	    }
188	
189	    @Override
190	    public String toString() {
191	        return new ToStringCreator(this)
192	
193	            .append("id", this.getId())
194	            .append("new", this.isNew())
195	            .append("lastName", this.getLastName())
196	            .append("firstName", this.getFirstName())
197	            .append("address", this.address)
198	            .append("city", this.city)
199	            .append("telephone", this.telephone)
200	            .append("email", this.email)
201	            .toString();
202	    }
203	}
