20	                "The request contains invalid or missing parameters");
21	        BindingResult bindingResult = ex.getBindingResult();
22	        if (bindingResult.hasErrors()) {
23	            List<String> errors = bindingResult.getFieldErrors().stream()
24	                    .map(fieldError -> fieldError.getField())
25	                    .distinct()
26	                    .toList();
27	            detail.setProperty("errors", errors);
28	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
29	                    .map(fieldError -> {
30	                        String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
31	                        String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
32	                        String message = "Field '%s' %s (rejected value: %s)".formatted(
33	                                fieldError.getField(), defaultMessage, rejectedValue);
34	                        return new ValidationMessageDto(message)
35	                                .putAdditionalProperty("field", fieldError.getField())
36	                                .putAdditionalProperty("rejectedValue", rejectedValue)
37	                                .putAdditionalProperty("defaultMessage", defaultMessage);
38	                    })
39	                    .toList();
40	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
41	        }
42	        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST).body(detail));
